/* Move-only owner of an SDL_GPUShader. */
class Shader {
public:
    Shader() = default;
    Shader(SDL_GPUDevice *device, SDL_GPUShader *shader) : device_(device), shader_(shader) {}
    ~Shader() { reset(); }

    Shader(const Shader &) = delete;
    Shader &operator=(const Shader &) = delete;

    Shader(Shader &&o) noexcept : device_(o.device_), shader_(o.shader_) {
        o.device_ = nullptr;
        o.shader_ = nullptr;
    }
    Shader &operator=(Shader &&o) noexcept {
        if (this != &o) {
            reset();
            device_ = o.device_;
            shader_ = o.shader_;
            o.device_ = nullptr;
            o.shader_ = nullptr;
        }
        return *this;
    }

    void reset() {
        if (device_ && shader_) SDL_ReleaseGPUShader(device_, shader_);
        device_ = nullptr;
        shader_ = nullptr;
    }
    SDL_GPUShader *get() const { return shader_; }
    SDL_GPUShader *release() {
        SDL_GPUShader *s = shader_;
        shader_ = nullptr;
        device_ = nullptr;
        return s;
    }
    explicit operator bool() const { return shader_ != nullptr; }

private:
    SDL_GPUDevice *device_ = nullptr;
    SDL_GPUShader *shader_ = nullptr;
};

/* Move-only owner of an SDL_GPUComputePipeline, carrying its thread group size. */
class ComputePipeline {
public:
    ComputePipeline() = default;
    ComputePipeline(SDL_GPUDevice *device, SDL_GPUComputePipeline *p, const Uint32 threads[3])
        : device_(device), pipeline_(p) {
        for (int i = 0; i < 3; ++i) threads_[i] = threads ? threads[i] : 1;
    }
    ~ComputePipeline() { reset(); }

    ComputePipeline(const ComputePipeline &) = delete;
    ComputePipeline &operator=(const ComputePipeline &) = delete;

    ComputePipeline(ComputePipeline &&o) noexcept : device_(o.device_), pipeline_(o.pipeline_) {
        for (int i = 0; i < 3; ++i) threads_[i] = o.threads_[i];
        o.device_ = nullptr;
        o.pipeline_ = nullptr;
    }
    ComputePipeline &operator=(ComputePipeline &&o) noexcept {
        if (this != &o) {
            reset();
            device_ = o.device_;
            pipeline_ = o.pipeline_;
            for (int i = 0; i < 3; ++i) threads_[i] = o.threads_[i];
            o.device_ = nullptr;
            o.pipeline_ = nullptr;
        }
        return *this;
    }

    void reset() {
        if (device_ && pipeline_) SDL_ReleaseGPUComputePipeline(device_, pipeline_);
        device_ = nullptr;
        pipeline_ = nullptr;
    }
    SDL_GPUComputePipeline *get() const { return pipeline_; }
    Uint32 thread_count(int axis) const { return threads_[axis]; }

    /* Groups needed to cover `total` invocations on the given axis. */
    Uint32 groups_for(Uint32 total, int axis) const {
        const Uint32 t = threads_[axis] ? threads_[axis] : 1;
        return (total + t - 1) / t;
    }
    explicit operator bool() const { return pipeline_ != nullptr; }

private:
    SDL_GPUDevice *device_ = nullptr;
    SDL_GPUComputePipeline *pipeline_ = nullptr;
    Uint32 threads_[3] = {1, 1, 1};
};

/* Move-only owner of the pack itself. */
class Pack {
public:
    Pack() { SDL_zero(pack_); }
    ~Pack() { close(); }

    Pack(const Pack &) = delete;
    Pack &operator=(const Pack &) = delete;

    Pack(Pack &&o) noexcept : pack_(o.pack_), open_(o.open_), error_(o.error_) {
        SDL_zero(o.pack_);
        o.open_ = false;
    }
    Pack &operator=(Pack &&o) noexcept {
        if (this != &o) {
            close();
            pack_ = o.pack_;
            open_ = o.open_;
            error_ = o.error_;
            SDL_zero(o.pack_);
            o.open_ = false;
        }
        return *this;
    }

    static Pack open_file(const char *path) {
        Pack p;
        p.open_ = S3PACK_OpenFile(&p.pack_, path);
        if (!p.open_) p.fail();
        return p;
    }
    static Pack open_memory(const void *data, std::size_t size, bool take_ownership = false) {
        Pack p;
        p.open_ = S3PACK_OpenMemory(&p.pack_, data, size, take_ownership);
        if (!p.open_) p.fail();
        return p;
    }

    void close() {
        if (open_) S3PACK_Close(&pack_);
        open_ = false;
    }

    bool good() const { return open_; }
    explicit operator bool() const { return open_; }
    const char *error() const { return error_ ? error_ : ""; }

    /* Pointer-like access so `pack->shader(...)` reads naturally. */
    Pack *operator->() { return this; }
    const Pack *operator->() const { return this; }

    const S3PACK_Pack &raw() const { return pack_; }
    Uint32 shader_count() const { return pack_.shader_count; }
    bool compute_only() const { return S3PACK_IsComputeOnly(&pack_); }
    const S3PACK_Entry *find(Uint32 key) const { return S3PACK_Find(&pack_, key); }
    bool contains(Uint32 key) const { return find(key) != nullptr; }

    Shader shader(SDL_GPUDevice *device, Uint32 key) {
        SDL_GPUShader *s = S3PACK_CreateShader(device, &pack_, key);
        if (!s) fail();
        return Shader(device, s);
    }

    ComputePipeline compute(SDL_GPUDevice *device, Uint32 key) {
        Uint32 threads[3] = {1, 1, 1};
        SDL_GPUComputePipeline *p = S3PACK_CreateComputePipeline(device, &pack_, key, threads);
        if (!p) fail();
        return ComputePipeline(device, p, threads);
    }

private:
    void fail() {
        error_ = S3PACK_GetError();
#ifdef S3PACK_USE_EXCEPTIONS
        throw std::runtime_error(error_ ? error_ : "s3pack: unknown error");
#endif
    }

    S3PACK_Pack pack_;
    bool open_ = false;
    const char *error_ = nullptr;
};

